import { CiType, GitProvider } from "@allurereport/core-api";
import { getEnv } from "../utils.js";
const GITLAB_DEFAULT_SERVER_URL = "https://gitlab.com";
const stripTrailingSlashes = (value) => value.replace(/\/+$/, "");
const getMergeRequestProjectUrl = () => getEnv("CI_MERGE_REQUEST_PROJECT_URL") || getEnv("CI_PROJECT_URL");
const getSourceRef = () => getEnv("CI_MERGE_REQUEST_SOURCE_BRANCH_NAME") || getEnv("CI_COMMIT_REF_NAME") || undefined;
const getServerUrl = () => stripTrailingSlashes(getEnv("CI_SERVER_URL") || GITLAB_DEFAULT_SERVER_URL);
const getRestApiUrl = () => stripTrailingSlashes(getEnv("CI_API_V4_URL") || `${getServerUrl()}/api/v4`);
const getGraphqlApiUrl = () => {
    const explicit = getEnv("CI_API_GRAPHQL_URL");
    if (explicit) {
        return stripTrailingSlashes(explicit);
    }
    const restApiUrl = getRestApiUrl();
    return restApiUrl.replace(/\/api\/v4$/, "/api/graphql");
};
export const gitlab = {
    type: CiType.Gitlab,
    get detected() {
        return getEnv("GITLAB_CI") !== "";
    },
    get repoName() {
        return getEnv("CI_PROJECT_NAME");
    },
    get jobUid() {
        return getEnv("CI_PROJECT_ID");
    },
    get jobUrl() {
        return `${getEnv("CI_PROJECT_URL")}/pipelines`;
    },
    get jobName() {
        return getEnv("CI_PROJECT_NAME");
    },
    get ciJobName() {
        return getEnv("CI_JOB_NAME");
    },
    get jobRunUid() {
        return getEnv("CI_PIPELINE_ID");
    },
    get jobRunUrl() {
        return getEnv("CI_PIPELINE_URL");
    },
    get jobRunName() {
        return getEnv("CI_PIPELINE_ID");
    },
    get jobRunBranch() {
        return getSourceRef() || "";
    },
    get pullRequestUrl() {
        const mergeRequestIID = getEnv("CI_MERGE_REQUEST_IID");
        if (!mergeRequestIID) {
            return "";
        }
        const projectUrl = stripTrailingSlashes(getMergeRequestProjectUrl());
        return projectUrl ? `${projectUrl}/-/merge_requests/${mergeRequestIID}` : "";
    },
    get pullRequestName() {
        return getEnv("CI_MERGE_REQUEST_TITLE");
    },
    get provider() {
        return GitProvider.Gitlab;
    },
    get repository() {
        const projectPath = getEnv("CI_PROJECT_PATH");
        return projectPath
            ? {
                slug: projectPath,
                url: getEnv("CI_PROJECT_URL") || undefined,
            }
            : undefined;
    },
    get sourceBranch() {
        return getSourceRef();
    },
    get targetBranch() {
        return getEnv("CI_MERGE_REQUEST_TARGET_BRANCH_NAME") || undefined;
    },
    get pullRequest() {
        const mergeRequestIid = getEnv("CI_MERGE_REQUEST_IID");
        return mergeRequestIid
            ? {
                id: mergeRequestIid,
                url: this.pullRequestUrl || undefined,
                title: getEnv("CI_MERGE_REQUEST_TITLE") || this.pullRequestName || undefined,
            }
            : undefined;
    },
    get projectId() {
        return getEnv("CI_PROJECT_ID");
    },
    get projectPath() {
        return getEnv("CI_PROJECT_PATH");
    },
    get projectDirectory() {
        return getEnv("CI_PROJECT_DIR");
    },
    get pipelineSource() {
        return getEnv("CI_PIPELINE_SOURCE");
    },
    get currentJobId() {
        return getEnv("CI_JOB_ID");
    },
    get currentJobUrl() {
        return getEnv("CI_JOB_URL");
    },
    get mergeRequestProjectId() {
        return getEnv("CI_MERGE_REQUEST_PROJECT_ID");
    },
    get restApiUrl() {
        return getRestApiUrl();
    },
    get graphqlApiUrl() {
        return getGraphqlApiUrl();
    },
    get ref() {
        return getSourceRef() || "";
    },
    get jobArtifactsUrlBase() {
        return (`${new URL(getServerUrl()).protocol}//${getEnv("CI_PROJECT_ROOT_NAMESPACE_SLUG")}.${getEnv("CI_PAGES_DOMAIN") || "gitlab.io"}` +
            `/-/${getEnv("CI_PROJECT_NAME")}/-/jobs/${this.currentJobId}/artifacts`);
    },
};
